import{c as e,Q as l,j as t,m as i}from"./chunks/framework.DOi4mjdC.js";const n="/assets/Nd2Nz%E8%BD%AC%E6%8D%A2%E7%A4%BA%E6%84%8F%E5%9B%BE-1%E6%96%B0.BT3xwzwJ.png",h=JSON.parse('{"title":"多核非对齐切分","description":"","frontmatter":{},"headers":[{"level":1,"title":"多核非对齐切分","slug":"多核非对齐切分"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/多核非对齐切分.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/多核非对齐切分.md"}'),s={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/多核非对齐切分.md"};function r(p,a,o,c,d,g){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="多核非对齐切分" tabindex="-1">多核非对齐切分 <a class="header-anchor" href="#多核非对齐切分" aria-label="Permalink to &quot;多核非对齐切分&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>多核场景，对矩阵进行切分时，若M、N、K无法整除singleCoreM 、singleCoreN、 singleCoreK时，就会出现尾块，即多核非对齐场景。如下图矩阵A、B的最后一行和最后一列的矩阵块：</p><p><img src="'+n+`" alt=""></p><p>此时，C矩阵中的R矩阵块，依然是通过A1*B1+A2*B2+A3*B3+A4*B4累加得到的，处理A1*B1、A2*B2、A3*B3、A4*B4等尾块时，需在kernel侧设置尾块大小，在不改变原有tiling的情况下，调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetTail.md" target="_blank" rel="noreferrer">SetTail</a>接口重新设置本次计算的singleCoreM/singleCoreN/singleCoreK，在处理尾块的时候按照设置的值也就是tailM/tailN/tailK进行搬运和计算。</p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>多核处理Matmul矩阵计算，存在尾块的场景。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>处理尾块调用的SetTail接口，需要在Iterate/IterateAll之前调用。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>Matmul多核非对齐场景的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_multi_core_unaligned" target="_blank" rel="noreferrer">Matmul多核非对齐切分算子样例</a>。该场景的关键代码示例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 处理尾块</span></span>
<span class="line"><span>int tailM = tiling.M - mCoreIndex * tiling.singleCoreM;</span></span>
<span class="line"><span>tailM = tailM &lt; tiling.singleCoreM ? tailM : tiling.singleCoreM;</span></span>
<span class="line"><span>int tailN = tiling.N - nCoreIndex * tiling.singleCoreN;</span></span>
<span class="line"><span>tailN = tailN &lt; tiling.singleCoreN ? tailN : tiling.singleCoreN;</span></span>
<span class="line"><span>// 当tailM &lt; singleCoreM 或 tailN &lt; singleCoreN时被认为需要处理尾块，此时可以调用SetTail接口进行设置</span></span>
<span class="line"><span>if (tailM &lt; tiling.singleCoreM || tailN &lt; tiling.singleCoreN) {</span></span>
<span class="line"><span>    matmulObj.SetTail(tailM, tailN);</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,12)])])}const m=e(s,[["render",r]]);export{h as __pageData,m as default};
